```

### API Routes

#### `/vercel/sandbox/pages/api/posts/index.js` (Posts API)
- Handles GET and POST methods
- GET: Returns hardcoded list of 2 posts
- POST: Creates new post with title and content validation
- Returns 405 for other methods

```javascript
export default function handler(req, res) {
  if (req.method === 'GET') {
    // Simulate fetching posts
    const posts = [
      { id: 1, title: 'First Post', content: 'This is the first post' },
      { id: 2, title: 'Second Post', content: 'This is the second post' }
    ];

    res.status(200).json(posts);
  } else if (req.method === 'POST') {
    const { title, content } = req.body;

    if (!title || !content) {
      return res.status(400).json({ error: 'Title and content are required' });
    }

    // Simulate creating a post
    const newPost = {
      id: Date.now(),
      title,
      content,
      createdAt: new Date().toISOString()
    };

    res.status(201).json(newPost);
  } else {
    res.setHeader('Allow', ['GET', 'POST']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}
```

#### `/vercel/sandbox/pages/api/posts/[id].js` (Single Post API)
- Handles GET, PUT, and DELETE methods for individual posts
- GET: Returns post by ID
- PUT: Updates post with new title/content
- DELETE: Deletes post
- Returns 405 for other methods

```javascript
export default function handler(req, res) {
  const { id } = req.query;

  if (req.method === 'GET') {
    // Simulate fetching a single post
    const post = {
      id: parseInt(id),
      title: `Post ${id}`,
      content: `This is the content for post ${id}`,
      createdAt: new Date().toISOString()
    };

    res.status(200).json(post);
  } else if (req.method === 'PUT') {
    const { title, content } = req.body;

    // Simulate updating a post
    const updatedPost = {
      id: parseInt(id),
      title: title || `Post ${id}`,
      content: content || `Updated content for post ${id}`,
      updatedAt: new Date().toISOString()
    };

    res.status(200).json(updatedPost);
  } else if (req.method === 'DELETE') {
    // Simulate deleting a post
    res.status(200).json({ message: `Post ${id} deleted successfully` });
  } else {
    res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}
```

### Components

#### `/vercel/sandbox/components/AppProvider.js`
- Custom React Context provider for application state
- Manages theme state (light/dark)
- Provides `useAppContext` hook for accessing theme context
- Used in `_app.js` as a wrapper

```javascript
import { createContext, useContext, useState } from 'react';

const AppContext = createContext();

export function AppProvider({ children }) {
  const [theme, setTheme] = useState('light');

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  );
}

export function useAppContext() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider');
  }
  return context;
}
```

### Styling

#### `/vercel/sandbox/styles/globals.css`
- Global CSS file imported in `_app.js`
- Uses plain CSS (no CSS-in-JS or preprocessors)
- Responsive grid layout for blog posts
- Google Fonts integration (Inter font)
- Color scheme: Blue (#0070f3) for links/buttons, gray (#333, #666) for text
- Includes styles for:
  - App container (max-width: 1200px, centered)
  - Header and navigation
  - Post grid (auto-fit columns, min 300px)
  - Post cards with borders and rounded corners
  - Comments section
  - Error pages
  - Buttons with hover effects

